    await symlink("/etc/passwd", join(local, "outside"));
    await writeFile(Buffer.concat([Buffer.from(join(local, "bad-")), Buffer.from([0xff]), Buffer.from(".txt")]), "x");
    const fifo = join(local, "fifo");
    const mkfifo = spawn("mkfifo", [fifo]);
